INSERT INTO public.robot_expo_students (student_id, student_name, status, inputs, video_prompt, spec_sheet, teacher_feedback, feedback_at, video, likes, current_version, history, updated_at)
VALUES
  ('진연우', '진연우', 'revision', '{"robotName":"Mars-3D","appearance":"바퀴 빼고 가로는 220cm정도 세로, 높이는 190cm정도 크기이다. 바퀴는 무한궤도(캐터필더)호 양옆에 있고 방향을 바꿀때 바퀴가 방향을 이동하게한다. 본체안에 3d프린터가 있고 양옆에는 기계팔이 있어서 주인이 cad를 주면 본체안에서 직접뽑고 화성 바닥으로  잉크를 만든다. 다 만들면 작업물이 나오면서 기계팔이 어디에 둘지 카메라 센서로 보고 그 위치에 둔다. 만약 주인이 위치를 지정하면 그곳에 둔다.하얀색이 대부분이다.","purpose":"만약 지구 온난화로 지구말고 화성에 가게되면 재료는 없고 기지를 만들어야 될때 필요한 로봇이다.","mainFunction":"이동기능,3d 프린팅 기술, 조작 운반  기술, 자동배치 기술","sensorName":"카메라 센서, 통신용 센서, 초음파 센서","sensorTarget":"지형, 작업물, 환경","sensorAction":"화성에서 돌아다니는  사람들을 피하면서 만들어진 것을 지정된 위치에 가져간다.","scienceTech":"인공지능 기술 및 로봇공학: 카메라로 보고 어디에서 쌓을지 무슨 벽이 필요할지 만들수 있다.\n재료공학 및 3D프린팅 기술: 화설 땅을 3D잉크로 쓸수있게 만들고 필요할때 만든다. 화성의 흙을 부드럽게 녹여서 잉크 사용가능 한정도의 \n통신 네트워크 기술: 화성 반대편에서도 지시를 내리고 화면을 보고 3D프린팅이 어느정도 만들어졌는지 확인할 수 있다.\n안전,환경 기술: 화성의 모랫 바람과 온도를 견딜 수 있다.","coreValues":"#효율성 #안전성","videoStyle":"정밀 메카닉 공학 시뮬레이션 스타일 (로봇 관절 구조와 내부 기계 작동 클로즈업)"}'::jsonb, '[동영상 제작] 만약 지구 온난화로 지구말고 화성에 가게되면 재료는 없고 기지를 만들어야 될때 필요한 로봇이다 현장에서 바퀴 빼고 가로는 220cm정도 세로, 높이는 190cm정도 크기이다. 바퀴는 무한궤도호 양옆에 있고 방향을 바꿀때 바퀴가 방향을 이동하게한다. 본체안에 3d프린터가 있고 양옆에는 기계팔이 있어서 주인이 cad를 주면 본체안에서 직접뽑고 화성 바닥으로 잉크를 만든다. 다 만들면 작업물이 나오면서 기계팔이 어디에 둘지 카메라 센서로 보고 그 위치에 둔다. 만약 주인이 위치를 지정하면 그곳에 둔다.하얀색이 대부분이다 외형의 로봇 ''Mars-3D''이 역동적으로 움직이며 작동하는 영상. 로봇의 카메라 센서, 통신용 센서, 라이다거리센서가 빛나며 지형, 작업물, 환경을 스캔한 뒤, 화성에서 돌아다니는 사람들을 피하면서 만들어진 것을 지정된 위치에 가져간다하며 이동기능,3d 프린팅 기술, 조작 운반 기술, 자동배치 기술하는 모습을 연속된 동작으로 생생하게 보여준다. 로봇의 기계 관절 움직임 클로즈업과 전신 작동 장면을 부드러운 카메라 워킹으로 담아낸 정밀 메카닉 공학 시뮬레이션 스타일 동영상.', '{"robotAndAppearance":{"title":"🤖 출품 로봇명 & 외형","robotName":"Mars-3D","appearance":"바퀴 빼고 가로는 220cm정도 세로, 높이는 190cm정도 크기이다. 바퀴는 무한궤도(캐터필더)호 양옆에 있고 방향을 바꿀때 바퀴가 방향을 이동하게한다. 본체안에 3d프린터가 있고 양옆에는 기계팔이 있어서 주인이 cad를 주면 본체안에서 직접뽑고 화성 바닥으로  잉크를 만든다. 다 만들면 작업물이 나오면서 기계팔이 어디에 둘지 카메라 센서로 보고 그 위치에 둔다. 만약 주인이 위치를 지정하면 그곳에 둔다.하얀색이 대부분이다."},"purpose":{"title":"🎯 개발 배경 및 목적","content":"만약 지구 온난화로 지구말고 화성에 가게되면 재료는 없고 기지를 만들어야 될때 필요한 로봇이다."},"mainFunction":{"title":"⚙️ 핵심 작동 기능 및 구조","content":"이동기능,3d 프린팅 기술, 조작 운반  기술, 자동배치 기술"},"sensorMechanism":{"title":"📡 스마트 감지 메커니즘 (센서명 / 감지 대상 / 작동 연동)","sensorName":"카메라 센서, 통신용 센서, 라이다(LiDAR)거리센서","sensorTarget":"지형, 작업물, 환경","sensorAction":"화성에서 돌아다니는  사람들을 피하면서 만들어진 것을 지정된 위치에 가져간다."},"scienceTech":{"title":"🔬 적용 융합 과학기술","content":"인공지능 기술 및 로봇공학: 카메라로 보고 어디에서 쌓을지 무슨 벽이 필요할지 만들수 있다.\n재료공학 및 3D프린팅 기술: 화설 땅을 3D잉크로 쓸수있게 만들고 필요할때 만든다.\n통신 네트워크 기술: 화성 반대편에서도 지시를 내리고 화면을 보고 3D프린팅이 어느정도 만들어졌는지 확인할 수 있다.\n안전,환경 기술: 화성의 모랫 바람과 온도를 견딜 수 있다."},"coreValues":{"title":"💎 추구하는 핵심 가치","content":"#효율성 #안전성"},"videoStyle":{"title":"🎨 영상 연출 스타일","content":"정밀 메카닉 공학 시뮬레이션 스타일 (로봇 관절 구조와 내부 기계 작동 클로즈업)"}}'::jsonb, '① 3D 프린팅 원리: 화성의 흙을 바로 잉크로 사용하는 것인지, 다른 재료와 섞어 출력 재료로 만드는 것인지 설명이 필요함. ② 센서 역할: 카메라는 작업물과 주변 사람을 인식하고, 라이다는 장애물까지의 거리를 측정하는 등 센서별 역할을 구분할 필요가 있음. 통신용 센서는 센서보다는 통신 장치로 설명하는 것이 적절함. ③ 실제로 무엇을 출력하고 어떻게 기지를 만드는지 구체화할 필요가 있음.', '2026-11-13T04:40:07.742Z', '{"type":"none","url":"","title":""}'::jsonb, 0, 2, '[{"version":1,"label":"버전 1 (최초 제출)","submittedAt":"2026-11-13T04:21:46.675Z","inputs":{"robotName":"Mars-3D","appearance":"바퀴 빼고 가로는 220cm정도 세로, 높이는 190cm정도 크기이다. 바퀴는 무한궤도(캐터필더)호 양옆에 있고 방향을 바꿀때 바퀴가 방향을 이동하게한다. 본체안에 3d프린터가 있고 양옆에는 기계팔이 있어서 주인이 CAD를 주면 본체안에서 직접뽑고 화성 바닥으로  잉크를 만든다. 다 만들면 작업물이 나오면서 기계팔이 어디에 둘지 카메라 센서로 보고 그 위치에 둔다. 만약 주인이 위치를 지정하면 그곳에 둔다.하얀색이 대부분이다.","purpose":"만약 지구 온난화로 지구 말고 화성에 가게 되면 재료는 없고 기지를 만들어야 될때 필요한 로봇이다.","mainFunction":"이동기능,3d 프린팅 기술, 조작 운반 기술, 자동배치 기술","sensorName":"카메라 센서, 통신용 센서, 라이다(LiDAR)거리센서","sensorTarget":"지형, 작업물, 환경","sensorAction":"화성에서 돌아다니는  사람들을 피하면서 만들어진 것을 지정된 위치에 가져간다.","scienceTech":"인공 지능 및 로봇 공학, 재료 공학 및 3d프린팅 기술, 안전 및 환경 기술","coreValues":"#효율성 #안전성","videoStyle":"정밀 메카닉 공학 시뮬레이션 스타일 (로봇 관절 구조와 내부 기계 작동 클로즈업)"},"videoPrompt":"[동영상 제작] 만약 지구 온난화로 지구 말고 화성에 가게 되면 재료는 없고 기지를 만들어야 될때 필요한 로봇이다 현장에서 바퀴 빼고 가로는 220cm정도 세로, 높이는 190cm정도 크기이다. 바퀴는 무한궤도호 양옆에 있고 방향을 바꿀때 바퀴가 방향을 이동하게한다. 본체안에 3d프린터가 있고 양옆에는 기계팔이 있어서 주인이 CAD를 주면 본체안에서 직접뽑고 화성 바닥으로 잉크를 만든다. 다 만들면 작업물이 나오면서 기계팔이 어디에 둘지 카메라 센서로 보고 그 위치에 둔다. 만약 주인이 위치를 지정하면 그곳에 둔다.하얀색이 대부분이다 외형의 로봇 ''Mars-3D''이 역동적으로 움직이며 작동하는 영상. 로봇의 카메라 센서, 통신용 센서, 라이다거리센서가 빛나며 지형, 작업물, 환경을 스캔한 뒤, 화성에서 돌아다니는 사람들을 피하면서 만들어진 것을 지정된 위치에 가져간다하며 이동기능,3d 프린팅 기술, 조작 운반 기술, 자동배치 기술하는 모습을 연속된 동작으로 생생하게 보여준다. 로봇의 기계 관절 움직임 클로즈업과 전신 작동 장면을 부드러운 카메라 워킹으로 담아낸 정밀 메카닉 공학 시뮬레이션 스타일 동영상.","specSheet":{"robotAndAppearance":{"title":"🤖 출품 로봇명 & 외형","robotName":"Mars-3D","appearance":"바퀴 빼고 가로는 220cm정도 세로, 높이는 190cm정도 크기이다. 바퀴는 무한궤도(캐터필더)호 양옆에 있고 방향을 바꿀때 바퀴가 방향을 이동하게한다. 본체안에 3d프린터가 있고 양옆에는 기계팔이 있어서 주인이 CAD를 주면 본체안에서 직접뽑고 화성 바닥으로  잉크를 만든다. 다 만들면 작업물이 나오면서 기계팔이 어디에 둘지 카메라 센서로 보고 그 위치에 둔다. 만약 주인이 위치를 지정하면 그곳에 둔다.하얀색이 대부분이다."},"purpose":{"title":"🎯 개발 배경 및 목적","content":"만약 지구 온난화로 지구 말고 화성에 가게 되면 재료는 없고 기지를 만들어야 될때 필요한 로봇이다."},"mainFunction":{"title":"⚙️ 핵심 작동 기능 및 구조","content":"이동기능,3d 프린팅 기술, 조작 운반 기술, 자동배치 기술"},"sensorMechanism":{"title":"📡 스마트 감지 메커니즘 (센서명 / 감지 대상 / 작동 연동)","sensorName":"카메라 센서, 통신용 센서, 라이다(LiDAR)거리센서","sensorTarget":"지형, 작업물, 환경","sensorAction":"화성에서 돌아다니는  사람들을 피하면서 만들어진 것을 지정된 위치에 가져간다."},"scienceTech":{"title":"🔬 적용 융합 과학기술","content":"인공 지능 및 로봇 공학, 재료 공학 및 3d프린팅 기술, 안전 및 환경 기술"},"coreValues":{"title":"💎 추구하는 핵심 가치","content":"#효율성 #안전성"},"videoStyle":{"title":"🎨 영상 연출 스타일","content":"정밀 메카닉 공학 시뮬레이션 스타일 (로봇 관절 구조와 내부 기계 작동 클로즈업)"}},"teacherFeedbackBefore":"","teacherFeedbackAfter":"과학 기술에 대한 구체적인 설명을 적어주세요."},{"version":2,"label":"버전 2 (1차 수정)","submittedAt":"2026-11-13T04:26:07.923Z","inputs":{"robotName":"Mars-3D","appearance":"바퀴 빼고 가로는 220cm정도 세로, 높이는 190cm정도 크기이다. 바퀴는 무한궤도(캐터필더)호 양옆에 있고 방향을 바꿀때 바퀴가 방향을 이동하게한다. 본체안에 3d프린터가 있고 양옆에는 기계팔이 있어서 주인이 cad를 주면 본체안에서 직접뽑고 화성 바닥으로  잉크를 만든다. 다 만들면 작업물이 나오면서 기계팔이 어디에 둘지 카메라 센서로 보고 그 위치에 둔다. 만약 주인이 위치를 지정하면 그곳에 둔다.하얀색이 대부분이다.","purpose":"만약 지구 온난화로 지구말고 화성에 가게되면 재료는 없고 기지를 만들어야 될때 필요한 로봇이다.","mainFunction":"이동기능,3d 프린팅 기술, 조작 운반  기술, 자동배치 기술","sensorName":"카메라 센서, 통신용 센서, 라이다(LiDAR)거리센서","sensorTarget":"지형, 작업물, 환경","sensorAction":"화성에서 돌아다니는  사람들을 피하면서 만들어진 것을 지정된 위치에 가져간다.","scienceTech":"인공지능 기술 및 로봇공학: 카메라로 보고 어디에서 